const end = new Date();
end.setUTCDate(end.getUTCDate() - 1);
const start = new Date(end);
start.setUTCDate(start.getUTCDate() - 27);
const fmt = d => d.toISOString().slice(0,10);

const sites = [
  { name:'بيت الريف', siteUrl:'https://bietalreef.ae/' },
  { name:'تطبيق بيت الريف', siteUrl:'https://app.bietalreef.ae/' },
  { name:'وياك', siteUrl:'https://weyaakai.bietalreef.ae/' }
];

return sites.map(site => ({
  json:{
    ...site,
    startDate:fmt(start),
    endDate:fmt(end),
    encodedSiteUrl:encodeURIComponent(site.siteUrl)
  }
}));

const responses = $input.all();
const sites = $('تجهيز خصائص Search Console').all();

return responses.map((item, index) => {
  const site = sites[index]?.json || {};
  const rows = Array.isArray(item.json?.rows) ? item.json.rows : [];
  const clicks = rows.reduce((sum,r)=>sum+Number(r.clicks||0),0);
  const impressions = rows.reduce((sum,r)=>sum+Number(r.impressions||0),0);
  const weightedPositionNumerator = rows.reduce((sum,r)=>sum+(Number(r.position||0)*Number(r.impressions||0)),0);
  const avgPosition = impressions ? weightedPositionNumerator / impressions : 0;
  const ctr = impressions ? clicks / impressions : 0;

  return {
    json:{
      site:site.name,
      property:site.siteUrl,
      period:`${site.startDate} → ${site.endDate}`,
      clicks,
      impressions,
      ctr_percent:Number((ctr*100).toFixed(2)),
      avg_position:Number(avgPosition.toFixed(2)),
      days_with_data:rows.length,
      daily:rows.map(r=>({
        date:r.keys?.[0] || '',
        clicks:Number(r.clicks||0),
        impressions:Number(r.impressions||0),
        ctr_percent:Number((Number(r.ctr||0)*100).toFixed(2)),
        position:Number(Number(r.position||0).toFixed(2))
      }))
    }
  };
});
